mapper.insert:
INSERT INTO daily_report_push_device (device_id, account_id, session_id, expo_token, enabled, updated_at)
SELECT #{deviceId}, #{accountId}, s.id, #{token}, TRUE, #{now} FROM account_session s
WHERE s.token_hash = #{hash} AND s.account_id = #{accountId} AND s.expires_at > #{now}
ON DUPLICATE KEY UPDATE account_id = #{accountId}, session_id = s.id, expo_token = #{token}, enabled = TRUE, updated_at = #{now}

mapper.select:
SELECT DISTINCT d.account_id FROM daily_report_push_device d JOIN account_session s ON s.id = d.session_id
    JOIN account a ON a.id = d.account_id JOIN company c ON c.account_id = d.account_id
    LEFT JOIN daily_report r ON r.account_id = d.account_id AND r.report_date = #{date}
WHERE  AND (r.id IS NULL OR (r.status = 'FAILED' AND r.generation_attempts < 2))
    AND NOT EXISTS(SELECT 1 FROM daily_report_generation_job j WHERE j.report_id = r.id AND j.status = 'UNKNOWN')
ORDER BY d.account_id LIMIT #{limit}
